555	export const MACHINE_BLOCK_END = '<!-- /claudinite-item -->';
556	
557	const BLOCK_RE = /<!-- claudinite-item -->\n?([\s\S]*?)\n?<!-- \/claudinite-item -->/;
558	
559	// The machine's half of a body, or null where there is no block at all.
560	export const machineBlockOf = (body) => BLOCK_RE.exec(String(body ?? ''))?.[1] ?? null;
561	
562	// The machine's half to read fields out of: the block where there is one, the whole
563	// body otherwise.
564	export const itemFieldText = (body) => machineBlockOf(body) ?? String(body ?? '');
565	
566	// Replace the block, or append one to a body that has none. The human's text is
567	// never rewritten — an append lands after it, separated by a blank line.
568	export function withMachineBlock(body, block) {
569	  const text = String(body ?? '');
570	  const wrapped = `${MACHINE_BLOCK_START}\n${block.replace(/\s*$/, '')}\n${MACHINE_BLOCK_END}`;
571	  if (BLOCK_RE.test(text)) return text.replace(BLOCK_RE, wrapped);
572	  return `${text.replace(/\s*$/, '')}\n\n${wrapped}\n`;
573	}
574	
575	// Apply an edit to whichever half is the machine's. Every writer that reshapes an
576	// item body — a Context section, code-work's delivered list, a stamped
577	// `Not-before` — goes through here, so it edits the block on a marked issue and the
578	// whole body on a `[claudinite-work]` item, with one call site either way.
579	export function editItemBody(body, edit) {
580	  const block = machineBlockOf(body);
581	  return block === null ? edit(String(body ?? '')) : withMachineBlock(body, edit(block));
582	}
583	
584	// The human's half of a body — everything the machine block is not. A marked
585	// issue's PARAMETERS are read from here and never from the block: re-asking clears
586	// the status and leaves the previous run's block standing, and a parser that read
587	// the whole body would find that stale copy beside the person's own field.
588	export const humanTextOf = (body) => String(body ?? '').replace(BLOCK_RE, '').trim();
589	
590	const NOT_BEFORE_RE = /^Not-before:[ \t]*(.*)$/m;
591	const BLOCKED_BY_RE = /^Blocked-by:[ \t]*(.*)$/m;
592	const REQUEST_RE = /^Request:[ \t]*#?(\d+)/m;
593	const MODEL_RE = /^Model:[ \t]*(\S+)/m;
594	const MERGE_RE = /^Merge:[ \t]*(\S+)/m;
595	const ENDS_WHEN_RE = /^Ends-when:[ \t]*#(\d+)[ \t]+(\S+)[ \t]*$/m;
596	const TARGET_BRANCH_RE = /^Target-branch:[ \t]*(\S+)[ \t]*$/m;
597	const TARGET_PR_RE = /^Target-pr:[ \t]*#?(\d+)[ \t]*$/m;
598	const SUPERSEDES_RE = /^Supersedes:[ \t]*(.*)$/m;
599	
600	// Build a work item body. The first line is the task path — the only thing an
601	// executor reads to locate the worker, validated in code before anything trusts
602	// it. Everything behavior-defining (model, ceiling, worker content, code-work
603	// command) is read from the tracked task files at HEAD, never from here.
604	export function workItemBody({
605	  taskPath, notBefore = null, blockedBy = [], context = [], delivered = [], reason = null,
606	  request = null, model = null, merge = null,
607	}) {
608	  const lines = [taskPath, ''];
609	  const fields = [];
610	  if (notBefore) fields.push(`${NOT_BEFORE_FIELD}: ${notBefore}`);
611	  if (blockedBy.length) fields.push(`${BLOCKED_BY_FIELD}: ${blockedBy.map((n) => `#${n}`).join(', ')}`);
612	  if (request) fields.push(`${REQUEST_FIELD}: #${request}`);
613	  if (model) fields.push(`${MODEL_FIELD}: ${model}`);
614	  if (merge) fields.push(`${MERGE_FIELD}: ${merge}`);
615	  if (fields.length) lines.push(...fields, '');
616	  lines.push('Execute the Claudinite task above.');
617	  if (context.length) {
618	    lines.push(
619	      'The Context section below is binding scope — do not re-decide it.',
620	      '',
621	      '### Context',
622	      ...context.map((c) => `- ${c}`),
623	    );
624	  }
625	  if (reason) lines.push('', '### Why the agent is here', '', `- ${reason}`);
626	  if (delivered.length) lines.push('', `### ${DELIVERED_HEADING}`, '', ...delivered.map((d) => `- ${d}`));
627	  return lines.join('\n') + '\n';
628	}
629	
630	// The `Blocked-by` numbers a body names, from a work item's body or from an
631	// ORDINARY issue's — a request marked for implementation states what it waits on in
632	// the same field spelling, and adoption carries it onto the item it births (§16.11).
633	export function parseBlockedBy(body) {
634	  const bb = BLOCKED_BY_RE.exec(String(body ?? ''))?.[1] ?? '';
635	  return [...bb.matchAll(/#(\d+)/g)].map((m) => Number(m[1]));
636	}
637	
638	// Parse an item body back into the facts the scheduler run and the executor read. A body
639	// with no first line, or whose fields are absent, yields nulls — absence is
640	// meaningful everywhere here and is never filled in with a default.
641	export function parseWorkItemBody(body) {
642	  const text = itemFieldText(body);
643	  const taskPath = text.split('\n').map((l) => l.trim()).find((l) => l !== '') ?? null;
644	  const nb = NOT_BEFORE_RE.exec(text)?.[1]?.trim() || null;
645	  const blockedBy = parseBlockedBy(text);
646	  const request = REQUEST_RE.exec(text) ? Number(REQUEST_RE.exec(text)[1]) : null;
647	  // An unrecognised family reads as absent rather than as itself: the item's model
648	  // is behaviour-defining, so the only values that leave this parser are ones the
649	  // engine can actually dispatch at (§16.7).
650	  const askedModel = MODEL_RE.exec(text)?.[1] ?? null;
651	  const model = REQUEST_MODELS.includes(askedModel) ? askedModel : null;
652	  // Same fencing as the model: an authorization that does not read as a policy
653	  // expression reads as absent, and absent is the safe end of this field — a run
654	  // that cannot read its permission opens a pull request and waits.
655	  const merge = policyFieldValue(MERGE_RE.exec(text)?.[1] ?? null);
656	  // Same fencing again, and here it is what keeps the janitor honest: a condition
657	  // it cannot evaluate must read as "no end condition", never as one that is met.
658	  const ends = ENDS_WHEN_RE.exec(text);
659	  const endsWhen = ends && ends[2] === ENDS_WHEN_CLOSED ? Number(ends[1]) : null;
660	  const targetBranch = TARGET_BRANCH_RE.exec(text)?.[1] ?? null;
661	  const targetPr = TARGET_PR_RE.exec(text) ? Number(TARGET_PR_RE.exec(text)[1]) : null;
662	  const supersedes = [...(SUPERSEDES_RE.exec(text)?.[1] ?? '').matchAll(/#(\d+)/g)].map((m) => Number(m[1]));
663	  return { taskPath, notBefore: nb, blockedBy, request, model, merge, endsWhen, targetBranch, targetPr, supersedes };
664	}
665	
666	// WHAT A MARKED ISSUE ASKS FOR (DESIGN §16.3, §16.7, §16.11) — read from the
667	// person's own text at every adoption, so each ask names its parameters afresh and
668	// nothing stale outranks a new one.
669	//
670	// Whoever files the issue puts these on its FIRST LINES, as one block ahead of the
671	// prose — `basics/skills/do-later/SKILL.md` is where that placement is prescribed and
672	// argued. The parser does not care where they sit; a person editing the issue, and a
673	// retry rewriting `Not-before`, do.
674	//
675	// `gated` is whether the issue's AUTHOR holds push access. A body is editable by
676	// whoever opened the issue where a label was write-gated by the platform, so the
677	// three behaviour-defining fields are honoured only for an author who could have
678	// applied them as labels anyway; an ungated ask still runs, at the default task and
679	// model and with no authorization to land anything.
680	export function parseRequestFields(body, { gated = false } = {}) {
681	  const text = humanTextOf(body);
682	  const asked = {
683	    task: /^Task:[ \t]*(\S+)/m.exec(text)?.[1] ?? null,
684	    model: MODEL_RE.exec(text)?.[1] ?? null,
685	    automerge: /^Automerge:[ \t]*(.+?)[ \t]*$/m.exec(text)?.[1] ?? null,
686	  };
687	  const blockedBy = parseBlockedBy(text);
688	  const notBefore = NOT_BEFORE_RE.exec(text)?.[1]?.trim() || null;
689	  if (!gated) return { task: null, model: null, merge: null, blockedBy, notBefore, ungated: Object.values(asked).some(Boolean) };
690	  return {
691	    task: /^[^/\s]+\/[^/\s]+$/.test(asked.task ?? '') ? asked.task : null,
692	    // An unrecognised family reads as absent rather than failing the request: a run
693	    // nobody can start would look accepted forever.
694	    model: REQUEST_MODELS.includes(asked.model) ? asked.model : null,

